var i=`0288-ajvar`;var n=`world-0288`;var a=`RS`;var r=`southern-europe`;var l=4;var s=68;var o={en:`Ajvar`,ua:`Айвар`};var g={en:`A traditional Serbia dish made with red bell pepper, eggplant, garlic, white vinegar. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Сербія. Основні інгредієнти: червоний солодкий перець, баклажан, часник, білий оцет. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var d=[{en:`Cut the vegetables evenly and roast at 200°C for about 35 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 35 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:35,i:[[`red-bell-pepper`,900,`g`],[`eggplant`,400,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`garlic`,5,`clove`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`sunflower-oil`,70,`ml`],[`white-vinegar`,30,`ml`],[`table-salt`,null,`to_taste`],[`white-granulated-sugar`,12,`g`]]}];var u={slug:i,id:n,country:`RS`,region:r,servings:4,minutes:68,title:o,text:g,steps:d};export{a as country,u as default,n as id,s as minutes,r as region,l as servings,i as slug,d as steps,g as text,o as title};